pub const Rm = @This();

opts: Opts,
state: State = .idle,

pub fn start(self: *Rm) Yield {
        return self.next();
}

pub noinline fn next(self: *Rm) Yield {
        while (((self.state != .done) and (self.state != .e))) {
            switch (self.state) {
.waiting_write_err => {
