},
.idle => {
self.state = .{ .parse_opts = .{ .args_slice = self.bltn().argsSlice() } };
            continue;
},
.parse_opts => {
var parse_opts = (&self.state.parse_opts);
            _ = &parse_opts;
            switch (parse_opts.state) {
.normal => {
